using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
class LayerAdjustment {
 public int Brightness,Hue,Saturation,Black,White=255,OutputBlack,OutputWhite=255;public float Gamma=1;public int[] Curve={0,64,128,192,255};
 public LayerAdjustment Copy(){var a=(LayerAdjustment)MemberwiseClone();a.Curve=(int[])Curve.Clone();return a;}
 public bool Identity {get{return Brightness==0&&Hue==0&&Saturation==0&&Black==0&&White==255&&OutputBlack==0&&OutputWhite==255&&Gamma==1&&Curve.SequenceEqual(new[]{0,64,128,192,255});}}
 public void Write(BinaryWriter w){foreach(int v in new[]{Brightness,Hue,Saturation,Black,White,OutputBlack,OutputWhite})w.Write(v);w.Write(Gamma);foreach(int v in Curve)w.Write(v);}
 public static LayerAdjustment Read(BinaryReader r){var a=new LayerAdjustment{Brightness=r.ReadInt32(),Hue=r.ReadInt32(),Saturation=r.ReadInt32(),Black=r.ReadInt32(),White=r.ReadInt32(),OutputBlack=r.ReadInt32(),OutputWhite=r.ReadInt32(),Gamma=r.ReadSingle()};for(int i=0;i<5;i++)a.Curve[i]=r.ReadInt32();if(Math.Abs((long)a.Brightness)>100||Math.Abs((long)a.Hue)>180||Math.Abs((long)a.Saturation)>100||a.Black<0||a.White>255||a.Black>=a.White||a.OutputBlack<0||a.OutputWhite>255||a.OutputBlack>=a.OutputWhite||float.IsNaN(a.Gamma)||a.Gamma<.1||a.Gamma>3||a.Curve.Any(v=>v<0||v>255))throw new InvalidDataException("Invalid layer adjustment");return a;}
 static double Clamp(double x){return Math.Max(0,Math.Min(1,x));}
 byte[] Tone(){var map=new byte[256];for(int i=0;i<256;i++){double x=Clamp(i/255.0+Brightness/100.0);x=Clamp((x*255-Black)/(White-Black));x=(OutputBlack+Math.Pow(x,1/Gamma)*(OutputWhite-OutputBlack))/255;double input=x*255;int lo=Math.Min(3,(int)(input/64)),x0=lo*64,x1=lo==3?255:(lo+1)*64;map[i]=(byte)Math.Round(Curve[lo]+(Curve[lo+1]-Curve[lo])*(input-x0)/(x1-x0));}return map;}
 public unsafe Bitmap Apply(Bitmap source){var result=(Bitmap)source.Clone();if(Identity)return result;var map=Tone();var data=result.LockBits(new Rectangle(0,0,result.Width,result.Height),ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{for(int y=0;y<result.Height;y++){byte* row=(byte*)data.Scan0+y*data.Stride;for(int x=0;x<result.Width;x++){byte* p=row+x*4;if(p[3]==0)continue;double r=map[p[2]]/255.0,g=map[p[1]]/255.0,b=map[p[0]]/255.0;if(Hue!=0||Saturation!=0){double max=Math.Max(r,Math.Max(g,b)),min=Math.Min(r,Math.Min(g,b)),delta=max-min,h=0,s=max==0?0:delta/max;if(delta>0)h=max==r?((g-b)/delta)%6:max==g?(b-r)/delta+2:(r-g)/delta+4;h=(h+Hue/60.0+12)%6;s=Clamp(s*(1+Saturation/100.0));double c=max*s,m=max-c,z=c*(1-Math.Abs(h%2-1));if(h<1){r=c;g=z;b=0;}else if(h<2){r=z;g=c;b=0;}else if(h<3){r=0;g=c;b=z;}else if(h<4){r=0;g=z;b=c;}else if(h<5){r=z;g=0;b=c;}else{r=c;g=0;b=z;}r+=m;g+=m;b+=m;}p[2]=(byte)Math.Round(Clamp(r)*255);p[1]=(byte)Math.Round(Clamp(g)*255);p[0]=(byte)Math.Round(Clamp(b)*255);}}}finally{result.UnlockBits(data);}return result;}
}
partial class Layer {
 public LayerAdjustment Adjustment=new LayerAdjustment();Bitmap adjusted,adjustmentSource;
 public void UpdatePixelAdjustment(Rectangle rect){if(rect.IsEmpty)return;MarkVisual(rect);if(Vectors.Count>0){InvalidateVectors();return;}PatchAdjustment(Image,rect);}public void PatchAdjustment(Bitmap source,Rectangle rect){if(adjusted==null||Adjustment.Identity||rect.IsEmpty)return;rect=Rectangle.Intersect(rect,new Rectangle(0,0,Image.Width,Image.Height));if(rect.Width<=0||rect.Height<=0)return;using(var crop=source.Clone(rect,PixelFormat.Format32bppArgb))using(var patch=Adjustment.Apply(crop)){var src=patch.LockBits(new Rectangle(Point.Empty,patch.Size),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var dst=adjusted.LockBits(rect,ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{var row=new byte[rect.Width*4];for(int y=0;y<rect.Height;y++){System.Runtime.InteropServices.Marshal.Copy(IntPtr.Add(src.Scan0,y*src.Stride),row,0,row.Length);System.Runtime.InteropServices.Marshal.Copy(row,0,IntPtr.Add(dst.Scan0,y*dst.Stride),row.Length);}}finally{adjusted.UnlockBits(dst);patch.UnlockBits(src);}}}
 public void InvalidateAdjustment(){MarkVisual(Rectangle.Empty);if(adjusted!=null)adjusted.Dispose();adjusted=null;adjustmentSource=null;}
 public Bitmap Display(Bitmap source,bool fresh=false){if(Adjustment.Identity)return source;if(fresh||adjustmentSource!=source)InvalidateAdjustment();if(adjusted==null){adjusted=Adjustment.Apply(source);adjustmentSource=source;}return adjusted;}
}
class CurveEditor:Control {
 public int[] Values={0,64,128,192,255};public Action Changed;int drag=-1;
 public CurveEditor(){DoubleBuffered=true;Size=new Size(280,200);Cursor=Cursors.Cross;}
 PointF Position(int i){return new PointF(12+(Width-24)*(i==4?255:i*64)/255f,Height-12-(Height-24)*Values[i]/255f);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.Clear(Theme.Bg);for(int i=0;i<5;i++){float x=12+(Width-24)*i/4f,y=12+(Height-24)*i/4f;g.DrawLine(Pens.Gray,x,12,x,Height-12);g.DrawLine(Pens.Gray,12,y,Width-12,y);}var pts=Enumerable.Range(0,5).Select(Position).ToArray();g.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Theme.Accent,2))g.DrawLines(pen,pts);foreach(var p in pts)g.FillEllipse(Brushes.Teal,p.X-5,p.Y-5,10,10);}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;drag=Enumerable.Range(0,5).OrderBy(i=>Math.Abs(Position(i).X-e.X)).First();Capture=true;SetValue(e.Y);}
 void SetValue(int y){Values[drag]=(int)Math.Round(Math.Max(0,Math.Min(255,(Height-12-y)*255.0/(Height-24))));Invalidate();if(Changed!=null)Changed();}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(drag>=0)SetValue(e.Y);}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);drag=-1;Capture=false;}
}
class AdjustmentDialog:Form {
 public LayerAdjustment Value;Bitmap original,preview;PictureBox picture=new PictureBox();bool loading;CurveEditor curve=new CurveEditor();System.Collections.Generic.List<Action> refresh=new System.Collections.Generic.List<Action>();
 public AdjustmentDialog(Layer layer){Value=layer.Adjustment.Copy();Text="Layer adjustments · "+layer.Name;Theme.Form(this);ClientSize=new Size(900,590);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;var raw=layer.RawRendered();float scale=Math.Min(1,Math.Min(540f/raw.Width,460f/raw.Height));original=new Bitmap(Math.Max(1,(int)(raw.Width*scale)),Math.Max(1,(int)(raw.Height*scale)));using(var g=Graphics.FromImage(original)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(raw,new Rectangle(Point.Empty,original.Size));}picture.SetBounds(340,20,540,485);picture.SizeMode=PictureBoxSizeMode.CenterImage;picture.BackColor=Color.White;Controls.Add(picture);var tabs=new TabControl{Left=12,Top=15,Width=310,Height=495};Controls.Add(tabs);
 var basic=new TabPage("Colour");tabs.TabPages.Add(basic);AddSlider(basic,"Brightness",-100,100,()=>Value.Brightness,v=>Value.Brightness=v,12);AddSlider(basic,"Hue (degrees)",-180,180,()=>Value.Hue,v=>Value.Hue=v,102);AddSlider(basic,"Saturation",-100,100,()=>Value.Saturation,v=>Value.Saturation=v,192);
 var levels=new TabPage("Levels");tabs.TabPages.Add(levels);AddSlider(levels,"Input black",0,254,()=>Value.Black,v=>Value.Black=Math.Min(v,Value.White-1),5);AddSlider(levels,"Input white",1,255,()=>Value.White,v=>Value.White=Math.Max(v,Value.Black+1),85);AddSlider(levels,"Gamma × 100",10,300,()=>(int)(Value.Gamma*100),v=>Value.Gamma=v/100f,165);AddSlider(levels,"Output black",0,254,()=>Value.OutputBlack,v=>Value.OutputBlack=Math.Min(v,Value.OutputWhite-1),245);AddSlider(levels,"Output white",1,255,()=>Value.OutputWhite,v=>Value.OutputWhite=Math.Max(v,Value.OutputBlack+1),325);
 var curves=new TabPage("Curves");tabs.TabPages.Add(curves);curve.Location=new Point(10,30);curve.Values=Value.Curve;curve.Changed=UpdatePreview;curves.Controls.Add(curve);curves.Controls.Add(new Label{Text="Drag the five points up or down.\nLeft: shadows · Right: highlights.\nBottom: darker · Top: brighter.",Left=10,Top=250,Width=280,Height=80});
 var reset=Theme.Button("Reset all",delegate{Value=new LayerAdjustment();curve.Values=Value.Curve;Sync();UpdatePreview();});reset.SetBounds(12,535,110,34);Controls.Add(reset);var apply=Theme.Button("Apply",delegate{DialogResult=DialogResult.OK;});apply.SetBounds(660,535,100,34);Controls.Add(apply);var cancel=Theme.Button("Cancel",delegate{DialogResult=DialogResult.Cancel;});cancel.SetBounds(775,535,100,34);Controls.Add(cancel);AcceptButton=apply;CancelButton=cancel;Controls.Add(new Label{Text="Editable layer adjustments · original artwork is preserved",Left=340,Top=508,Width=540,Height=22});Theme.Apply(this);picture.BackColor=Color.White;UpdatePreview();}
 void AddSlider(Control parent,string title,int min,int max,Func<int> get,Action<int> set,int y){var label=new Label{Left=12,Top=y,Width=270,Height=24};var slider=new TrackBar{Left=8,Top=y+25,Width=275,Height=35,Minimum=min,Maximum=max,Value=get(),TickStyle=TickStyle.None};Action sync=delegate{slider.Value=get();label.Text=title.StartsWith("Gamma")?"Gamma · "+(get()/100f).ToString("0.00"):title+" · "+get();};refresh.Add(sync);sync();slider.ValueChanged+=delegate{if(loading)return;set(slider.Value);Sync();UpdatePreview();};parent.Controls.Add(label);parent.Controls.Add(slider);}
 void Sync(){loading=true;foreach(var action in refresh)action();loading=false;curve.Invalidate();}
 void UpdatePreview(){var next=Value.Apply(original);picture.Image=next;if(preview!=null)preview.Dispose();preview=next;}
 protected override void Dispose(bool disposing){if(disposing){picture.Image=null;if(preview!=null)preview.Dispose();if(original!=null)original.Dispose();}base.Dispose(disposing);}
}
partial class Studio {
 void ShowAdjustments(){if(canvas.Doc==null||canvas.Doc.Selected.IsLocked)return;canvas.EndStroke();var layer=canvas.Doc.Selected;using(var dialog=new AdjustmentDialog(layer))if(dialog.ShowDialog(this)==DialogResult.OK){ApplyAdjustment(layer,dialog.Value);}}
 void ApplyAdjustment(Layer layer,LayerAdjustment value){if(layer.IsLocked)return;Push(undo,layer);redo.Clear();layer.Adjustment=value.Copy();layer.InvalidateAdjustment();Changed();RefreshLayers();}
}
}
